SELECT (CAST('2007-12-31 23:59:59' AS DATE) - CAST('2007-12-30' AS DATE)) AS "delta", (CAST('2007-10-07' AS DATE) - CAST('0001-01-01' AS DATE) + 366) AS "day_no", (CAST(NULL AS DATE) - CAST('0001-01-01' AS DATE) + 366) IS NULL AS "null_day", (CAST('2000-02-28' AS DATE) - CAST('2000-03-01' AS DATE)) AS "leap_delta", STRING_AGG(CAST("k" AS TEXT), ';' ORDER BY "k" NULLS FIRST) AS "ids" FROM "dsl_eq_left" WHERE '2019-07-08 00:00:00' = '2019-07-08 00:00:00';
